from typing import List, Optional

# Definition for singly-linked list.
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def nodesBetweenCriticalPoints(self, head: Optional[ListNode]) -> List[int]:
        node_position_index = 0
        critical_point_indices = []
        value_of_previous_node = head.val
        
        current_traversal_node = head

        while current_traversal_node.next:
            if (value_of_previous_node - current_traversal_node.val) * \
               (current_traversal_node.val - current_traversal_node.next.val) < 0:
                critical_point_indices.append(node_position_index)
            
            value_of_previous_node = current_traversal_node.val
            current_traversal_node = current_traversal_node.next
            
            node_position_index += 1

        total_critical_points = len(critical_point_indices)

        if total_critical_points < 2:
            return [-1, -1]

        minimum_distance = float('inf')
        for i in range(1, total_critical_points):
            minimum_distance = min(minimum_distance,
                                   critical_point_indices[i] - critical_point_indices[i-1])
        
        maximum_distance = critical_point_indices[-1] - critical_point_indices[0]

        return [minimum_distance, maximum_distance]